MOD = 10**9 + 7

def power(base, exponent, mod):
    result = 1
    base = base % mod
    while exponent > 0:
        if exponent % 2 == 1:
            result = (result * base) % mod
        exponent = exponent >> 1
        base = (base * base) % mod
    return result

def compute_F(S):
    n = len(S)
    total_sum = 0

    for c in set(S):
        count_c = S.count(c)
        total_sum += power(count_c, len(set(S)), MOD)
        total_sum %= MOD

